{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    mins = [seg['minimum'] for seg in segments]
    caps = [seg['capacity'] for seg in segments]
    if budget < sum(mins) or budget > sum(caps):
        raise ValueError('Infeasible budget')
    alloc = mins[:]
    remaining = budget - sum(alloc)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] < seg['capacity']:
                score = seg['importance'] / (alloc[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError('Cannot allocate remaining budget')
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {seg['name']: alloc[i] for i, seg in enumerate(segments)}
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}"
